import { expect, test, uniqueName } from "../../fixtures";

const examples = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

test.describe("reject invalid vendor fields", () => {
  for (const { field, value } of examples) {
    test(`rejects ${field} set to ${JSON.stringify(value)}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const body: Record<string, unknown> = {
        name: uniqueName("Vendor"),
        category: "software",
        contact_email: "billing@vendor.test",
      };
      body[field] = value;

      // Act
      const response = await member.post("/api/vendors", { data: body });

      // Assert
      const text = await response.text();
      expect(response.status(), text).toBe(422);
      const payload = JSON.parse(text) as {
        error: { code: string; fields: { field: string; message: string }[] };
      };
      expect(payload.error.code, text).toBe("validation_error");
      expect(
        payload.error.fields.map((f) => f.field),
        text,
      ).toContain(field);
    });
  }
});
